#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzTexture(int tex,float2 uv) { return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_SPEED;
uniform float amzp_CYCLE;
uniform float amzp_ROT_Y;
uniform float amzp_ROT_X;
uniform float amzp_ROT_SPEED;
uniform float amzp_FBM_SCALE;
uniform float amzp_FBM_OCT;
uniform float amzp_FBM_PERSIST;
uniform float amzp_FOCAL_DEPTH;
uniform float amzp_DISK_MIN;
uniform float amzp_DISK_SCALE;
layout(color) uniform half4 amzp_COLOR_BASE;
uniform float amzp_WHITE_GAIN;
uniform float amzp_GAMMA;
uniform float amzp_WHITEOUT;
float3 hash33(float3 p3){
    p3 = fract(p3 * float3(0.1031, 0.11369, 0.13787));
    p3 += dot(p3, p3.yxz + 19.19);
    return -1.0 + 2.0 * fract(float3(
        (p3.x + p3.y) * p3.z,
        (p3.x + p3.z) * p3.y,
        (p3.y + p3.z) * p3.x
    ));
}
float simplexNoise(float3 p){
    const float K1 = 0.333333333;
    const float K2 = 0.166666667;
    float3 i = floor(p + (p.x + p.y + p.z) * K1);
    float3 d0 = p - (i - (i.x + i.y + i.z) * K2);
    float3 e = step(float3(0.0), d0 - d0.yzx);
    float3 i1 = e * (1.0 - e.zxy);
    float3 i2 = 1.0 - e.zxy * (1.0 - e);
    float3 d1 = d0 - (i1 - float3(1.0) * K2);
    float3 d2 = d0 - (i2 - float3(2.0) * K2);
    float3 d3 = d0 - (float3(1.0) - float3(3.0) * K2);
    float4 h = max(0.6 - float4(dot(d0,d0), dot(d1,d1), dot(d2,d2), dot(d3,d3)), 0.0);
    float4 n = h * h * h * h * float4(dot(d0, hash33(i)), dot(d1, hash33(i + i1)), dot(d2, hash33(i + i2)), dot(d3, hash33(i + float3(1.0))));
    return dot(float4(31.316), n);
}
float fbm3(float3 p){
    float f = 0.0;
    float scale = amzp_FBM_SCALE;
    float amp = 0.75;
    int oct = int(clamp(amzp_FBM_OCT, 1.0, 8.0));
    const int MAX_OCT = 8;
    for (int i=0; i<MAX_OCT; ++i){
        if (i >= oct) break;
        f += simplexNoise(p * scale) * amp;
        amp *= amzp_FBM_PERSIST;
        scale *= 2.0;
    }
    return min(f, 1.0);
}
float3x3 rotY(float a){ return float3x3(cos(a),0.0,sin(a), 0.0,1.0,0.0, -sin(a),0.0,cos(a)); }
float3x3 rotX(float a){ return float3x3(1.0,0.0,0.0, 0.0,cos(a),sin(a), 0.0,-sin(a),cos(a)); }
void amzRender(){
    float2 R = screen.zw;
    float2 frag = amzScreenNorm() * R;
    float t2 = max(amzp_CYCLE, 1e-3);
    float t = mod(time, t2) / t2;
    float2 q = frag / R;
    float2 p = (2.0 * frag - R) / min(R.y, R.x);
    p += float2(0.0, -0.1);
    float ay = amzp_ROT_Y;
    float ax = amzp_ROT_X;
    float3x3 m = rotX(ax) * rotY(ay);
    float3 v = float3(p, 1.0);
    v = m * v;
    float v_xy = length(v.xy);
    float z = v.z / max(v_xy, 1e-5);
    float focal_depth = amzp_FOCAL_DEPTH;
    float whiteoutSel = float(int(amzp_WHITEOUT));
    if (whiteoutSel > 0.5){
        float wf = smoothstep(0.65, 0.9, t);
        focal_depth = mix(0.15, 0.015, wf);
    }
    float2 polar;
    float p_len = length(v.xy);
    polar.y = z * focal_depth + time * amzp_SPEED;
    float a = atan(v.y, v.x);
    a = 0.5 + 0.5 * a / 3.141592653589793;
    a -= time * amzp_ROT_SPEED;
    float x = fract(a);
    if (x >= 0.5) x = 1.0 - x;
    polar.x = x;
    float val = 0.45 + 0.55 * fbm3(float3(float2(2.0, 0.5) * polar, 0.15 * time));
    val = clamp(val, 0.0, 1.0);
    float3 baseCol = amzp_COLOR_BASE.rgb;
    float3 col = baseCol * float3(val);
    float3 white = amzp_WHITE_GAIN * float3(smoothstep(0.55, 1.0, val));
    col += white;
    col = clamp(col, 0.0, 1.0);
    float w_total = 0.0;
    float w_out = 0.0;
    if (whiteoutSel > 0.5){
        float w_in = abs(1.0 - smoothstep(0.0, 0.25, t));
        w_out = abs(smoothstep(0.8, 1.0, t));
        w_total = max(w_in, w_out);
    }
    float disk_size = max(amzp_DISK_MIN, amzp_DISK_SCALE * w_out);
    float disk_col = exp(-(p_len - disk_size) * 4.0);
    col += clamp(float3(disk_col), 0.0, 1.0);
    if (whiteoutSel > 0.5){
        col = mix(col, float3(1.0), w_total);
    }
    col = pow(max(col, 0.0), float3(amzp_GAMMA));
    amzOutput = float4(col, 1.0);
}

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

